describe('Loading Skeleton Display During API Fetch', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display loading skeleton while API data is fetching', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchData');

    cy.get('[data-testid="load-button"]').click();

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="loading-skeleton"]').should('have.class', 'skeleton-animated');

    cy.wait('@fetchData');

    cy.get('[data-testid="loading-skeleton"]').should('not.exist');
    cy.get('[data-testid="data-content"]').should('be.visible');
  });

  it('should hide skeleton and display content after API response completes', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        items: [
          { id: 1, title: 'Item 1', description: 'Description 1' },
          { id: 2, title: 'Item 2', description: 'Description 2' }
        ]
      }
    }).as('fetchDataSuccess');

    cy.get('[data-testid="load-button"]').click();

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');

    cy.wait('@fetchDataSuccess');

    cy.get('[data-testid="loading-skeleton"]').should('not.exist');
    cy.get('[data-testid="data-content"]').should('be.visible');
    cy.get('[data-testid="data-item"]').should('have.length', 2);
    cy.get('[data-testid="data-item"]').first().should('contain', 'Item 1');
  });

  it('should display skeleton on page load with auto-fetch enabled', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(1500);
      });
    }).as('autoFetchData');

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="data-content"]').should('not.exist');

    cy.wait('@autoFetchData');

    cy.get('[data-testid="loading-skeleton"]').should('not.exist');
    cy.get('[data-testid="data-content"]').should('be.visible');
  });

  it('should handle API error gracefully after skeleton display', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('fetchDataError');

    cy.get('[data-testid="load-button"]').click();

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');

    cy.wait('@fetchDataError');

    cy.get('[data-testid="loading-skeleton"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');
  });

  it('should display multiple skeletons for list items', () => {
    cy.intercept('GET', '/api/items', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchItems');

    cy.get('[data-testid="load-items-button"]').click();

    cy.get('[data-testid="skeleton-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="skeleton-item"]').each(($skeleton) => {
      cy.wrap($skeleton).should('have.class', 'skeleton-animated');
    });

    cy.wait('@fetchItems');

    cy.get('[data-testid="skeleton-item"]').should('not.exist');
    cy.get('[data-testid="item-card"]').should('be.visible');
  });
});
